def _normalise(value):
 if type(value)is bool:return int(value)
 if isinstance(value,list):return [_normalise(item)for item in value]
 if isinstance(value,dict):return {key:_normalise(item)for key,item in value.items()}
 return value
import json,os,tempfile
from pathlib import Path
def solve(path,value):
 text=json.dumps(_normalise(value),ensure_ascii=False,allow_nan=False)
 target=Path(path);fd,name=tempfile.mkstemp(dir=target.parent,prefix='.publish-')
 try:
  with os.fdopen(fd,'w',encoding='utf-8')as f:f.write(text)
  os.replace(name,target)
 finally:
  if os.path.exists(name):os.unlink(name)
